  assert(b.pixels>90);assert(b.left>=2&&b.right<W-2&&b.top>=2&&b.bottom===pivot.y-1,`Escaped frame/ground pivot: ${JSON.stringify(b)}`);
  for(let i=0;i<png.data.length;i+=4){assert(png.data[i+3]===0||png.data[i+3]===255);if(!png.data[i+3])assert.equal(png.data.readUInt32BE(i),0);}
