  let scale,side=0,sx=0,sy=0;
  if(type==='farm'){side=Math.min(sprite.width,sprite.height);sx=Math.floor((sprite.width-side)/2);sy=Math.floor((sprite.height-side)/2);scale=48/side;}
  else if(type==='tower')scale=[60,72,84][stage]/sprite.height;
