  // uniformly fitted 64px PNG, not a CSS zoom that clips the art.
  const b=bounds(frame),scale=Math.min(56/b.width,56/b.height),w=Math.round(b.width*scale),h=Math.round(b.height*scale),out=new PNG({width:64,height:64});out.data.fill(0);
