  const loaded=Object.fromEntries(Object.keys(batches).map(key=>[key,loadBatch(key)])),originalTower=loadBatch('a',true),frames=[],atlas=new PNG({width:W*9,height:H*9});atlas.data.fill(0);
  const finalFile=path.join(work,'sources/key-final.png'),finalPNG=clean(finalFile),finalBatch={file:finalFile,p:finalPNG,x:cuts(finalPNG,'x',3),y:cuts(finalPNG,'y',3)},finalTypes=['shrine','port','inn'];
  for(const [index,b] of spec.buildings.entries())for(let stage=0;stage<3;stage++){
    const key=Object.keys(batches).find(k=>batches[k].includes(b.id)),finalIndex=finalTypes.indexOf(b.id),row=finalIndex>=0?finalIndex:batches[key].indexOf(b.id),batch=finalIndex>=0?finalBatch:b.id==='tower'?originalTower:loaded[key],sprite=extract(batch,row,stage),p=pixelize(sprite,b.id,stage),subject=validate(p.frame);
    const x=(index%3*3+stage)*W,y=Math.floor(index/3)*H,image=`assets/sprites/buildings/${b.id}/level-${stage+1}.png`;
    write(path.join(work,'ready',b.id,`level-${stage+1}.png`),p.frame);blit(p.frame,atlas,x,y);
    write(path.join(work,'thumbnails',b.id,`level-${stage+1}.png`),thumbnail(p.frame));
    frames.push({type:b.id,name:b.name,stage:stage+1,motif:b.motif,description:b.stages[stage],gameLevels:stage===2?[7,G.maxLevel({type:b.id})]:[stage*3+1,stage*3+3],image,frame:{x,y,width:W,height:H},pivot,subject,
      source:{image:path.relative(root,batch.file).replaceAll('\\','/'),rect:{x0:batch.x[stage],x1:batch.x[stage+1],y0:batch.y[row],y1:batch.y[row+1]},width:sprite.width,height:sprite.height,crop:p.sourceCrop,uniformScale:p.scale}});
  }
  for(const b of spec.buildings){const family=frames.filter(f=>f.type===b.id);console.log(b.id,family.map(f=>`${f.subject.width}x${f.subject.height}`).join(' -> '));for(let stage=1;stage<3;stage++){const a=family[stage-1].subject,z=family[stage].subject;if(b.id==='farm')assert.equal(z.width*z.height,a.width*a.height);else assert(z.height>a.height,`Height not growing: ${b.id}`);}}
  write(path.join(work,'buildings-atlas.png'),atlas);write(path.join(work,'buildings-atlas-2x.png'),enlarge(atlas,2));
  json(path.join(work,'buildings-atlas.json'),{version,columns:9,rows:9,frameWidth:W,frameHeight:H,width:atlas.width,height:atlas.height,pivot,style:'Approved thin dark-brown outline, flat cartoon, muted gray-blue palette; uniformly pixelized, height-led structural upgrades',frames});
  const buildings=[],archive={};
  for(const b of spec.buildings){
    const family=frames.filter(f=>f.type===b.id),sheet=new PNG({width:W*3,height:H});sheet.data.fill(0);
    family.forEach((f,stage)=>blit(PNG.sync.read(fs.readFileSync(path.join(work,'ready',b.id,`level-${stage+1}.png`))),sheet,stage*W,0));
    const image=`${b.id}.png`,bytes=PNG.sync.write(sheet);fs.mkdirSync(path.join(work,'by-building'),{recursive:true});fs.writeFileSync(path.join(work,'by-building',image),bytes);archive[image]=bytes;
    buildings.push({type:b.id,name:b.name,image,width:sheet.width,height:sheet.height,frames:family.map((f,stage)=>({stage:stage+1,gameLevels:f.gameLevels,frame:{x:stage*W,y:0,width:W,height:H},pivot,subject:f.subject}))});
  }
  const grouped={version,frameWidth:W,frameHeight:H,columns:3,rows:1,stageOrder:[1,2,3],pivot,buildings};
