    for(let stage=0;stage<3;stage++){const frame=PNG.sync.read(fs.readFileSync(path.join(work,'ready',type,`level-${stage+1}.png`)));for(let y=0;y<H;y++)assert.deepEqual(sheet.data.subarray((y*sheet.width+stage*W)*4,(y*sheet.width+(stage+1)*W)*4),frame.data.subarray(y*W*4,(y+1)*W*4));}
